def view_state(catalog,version,selected_hazard=None):
    all_assets={}
    for v in catalog.values():all_assets.update(v['assets'])
    return {'available_hazards':sorted(all_assets),'selected_hazard':selected_hazard,'data_url':all_assets.get(selected_hazard)}

